import { realpathSync } from "node:fs";
import { basename, relative, resolve, sep } from "node:path";
export const ARTIFACTS_MANIFEST_FILENAME = "artifacts.json";
const existingRealPath = (filePath) => {
    try {
        return realpathSync(filePath);
    }
    catch {
        return filePath;
    }
};
export const normalizeArtifactPath = (filePath, cwd) => {
    const path = relative(resolve(cwd), resolve(cwd, filePath)).split(sep).join("/");
    return path || ".";
};
export const createReportArtifact = (filePath, cwd, name = basename(filePath)) => ({
    name,
    path: normalizeArtifactPath(filePath, cwd),
});
export const deduplicateDumpInputs = (dumps, cwd) => {
    const seen = new Set();
    return dumps.reduce((acc, dump) => {
        const absolutePath = resolve(cwd, dump.path);
        const dedupeKey = existingRealPath(absolutePath);
        if (seen.has(dedupeKey)) {
            return acc;
        }
        seen.add(dedupeKey);
        acc.push({
            ...dump,
            path: absolutePath,
        });
        return acc;
    }, []);
};
